/**
 * Response returned when a CA certificate is generated.
 *
 * Includes the private key PEM, which is returned **once** and never stored
 * or retrievable again — when the custodian produced one at all. Under
 * `vault_pki` custody the key was born inside Vault and there is nothing to
 * return, which is the point of that custodian rather than a shortcoming of
 * this response.
 */
export interface GeneratedCaCertificate {
  /**
   * The issuers above [`Self::public_cert_pem`], concatenated PEM, nearest
   * issuer first and the root last.
   *
   * `None` for a CA that is its own root, which is every CA AXIAM generated
   * before Vault's PKI engine was an option. Present for a `vault_pki` CA,
   * where it is the only copy of the root certificate anything outside Vault
   * will ever see — a relying party cannot validate an AXIAM-issued leaf
   * without it, and `root/generate/internal` returns it exactly once.
   */
  chain_pem?: string | null;
  /** `created_at`. */
  created_at: string;
  /** SHA-256 fingerprint of the certificate. */
  fingerprint: string;
  /** `id`. */
  id: string;
  /** `key_algorithm`. */
  key_algorithm: KeyAlgorithm;
  /**
   * Which custodian holds this CA's signing key.
   *
   * Recorded per CA rather than read from configuration, so adopting a new
   * custodian does not strand the CAs that already exist. Not secret — an
   * operator needs to see it, and it discloses only where a key is kept.
   */
  key_custody?: string;
  /**
   * Where the custodian put the key. A Vault path under its mount; `None` for
   * database custody, whose locator is the row itself.
   */
  key_locator?: string | null;
  /**
   * Whether this CA is offered as a trust anchor for mutual TLS.
   *
   * When set, the server exports this CA's **public** certificate to the
   * bundle named by `AXIAM__SERVER__TLS__CLIENT_CA_BUNDLE_PATH` at startup and
   * turns client-certificate authentication on (`optional`) if the operator
   * has not configured it explicitly. A client presenting a certificate that
   * chains to this CA is then verified by the TLS layer itself, which is what
   * `axiam_pki::mtls` needs to authenticate an IoT device or a service account
   * by certificate rather than by secret.
   *
   * # What is and is not copied
   *
   * Only `public_cert_pem` — the certificate. The **private key stays where
   * its custodian put it** (Vault, or sealed into the row) and is never
   * written to the server volume. A trust anchor is public by construction: it
   * is what the server hands every client during the TLS handshake, and every
   * device that has to validate the chain already holds a copy.
   *
   * # Why a restart
   *
   * rustls builds its `RootCertStore` once, when the listener is constructed,
   * and actix-web binds that config for the process's life. Toggling this
   * changes what the *next* boot trusts, and the API says so in its response
   * rather than pretending the change took effect.
   *
   * Defaults to `false`, so a deployment that never touches this keeps exactly
   * the TLS posture it has today.
   */
  mtls_trust_anchor?: boolean;
  /** Validity end. */
  not_after: string;
  /** Validity start. */
  not_before: string;
  /** The organization this CA belongs to. */
  organization_id: string;
  /**
   * The CA in this organization that signed this one.
   *
   * `None` for an organization-level CA, which is either self-signed or
   * imported and has no parent inside AXIAM.
   */
  parent_ca_id?: string | null;
  /**
   * PEM-encoded private key — returned only on generation, and only when there
   * is one to return.
   *
   * Absent under `vault_pki` custody, where the key was generated inside Vault
   * and no API exports it. The field is omitted rather than sent as `null` so
   * a client that has always read it keeps working unchanged for every
   * custodian that does produce a key.
   *
   * **Secret.** Redacted from every string, log and JSON rendering; call
   * `.expose()` to read it.
   */
  private_key_pem?: Sensitive<string>;
  /**
   * PEM-encoded public certificate.
   *
   * The certificate that *signs*, which under `vault_pki` custody is the
   * intermediate rather than the root beneath which it was created.
   */
  public_cert_pem: string;
  /** `status`. */
  status: CertificateStatus;
  /** The certificate subject (e.g., `CN=ACME Corp Root CA`). */
  subject: string;
  /**
   * The tenant this CA signs for, when it is a tenant signing CA.
   *
   * `None` for an organization-level CA — the trust anchor, and the only kind
   * that existed before tenant signing CAs. `Some` for an intermediate created
   * under one, which exists so a tenant's user, service and device
   * certificates chain through a CA that can be revoked and replaced without
   * touching the anchor the rest of the estate trusts.
   */
  tenant_id?: string | null;
}

/** Wire twin of {@link GeneratedCaCertificate} — plain strings, never logged. */
export interface GeneratedCaCertificateWire {
  chain_pem?: string | null;
  created_at: string;
  fingerprint: string;
  id: string;
  key_algorithm: KeyAlgorithm;
  key_custody?: string;
  key_locator?: string | null;
  mtls_trust_anchor?: boolean;
  not_after: string;
  not_before: string;
  organization_id: string;
  parent_ca_id?: string | null;
  private_key_pem?: string;
  public_cert_pem: string;
  status: CertificateStatus;
  subject: string;
  tenant_id?: string | null;
}

